def max_sub_array_sum_repeated(arr, n, k):
    # Function to find maximum sum of a subarray in one dimensional array.
    def kadane(array):
        maximum = current_max = array[0]
        for i in range(1, len(array)):
            current_max = max(array[i], current_max + array[i])
            maximum = max(maximum, current_max)
        return maximum

    # If there is only one repetition
    max_kadane = kadane(arr)

    # If there are two repetitions
    max_wrap = 0
    max_ending_here = 0
    max_beginning_here = 0
    for i in range(0, n):
        max_ending_here = max_ending_here + arr[i]
        if max_ending_here < 0:
            max_ending_here = 0
        if arr[i] > max_ending_here:
            max_ending_here = arr[i]
        max_wrap = max(max_wrap, max_ending_here)
    for i in range(0, n - 1):
        arr[i] = arr[i] + arr[n - 1 - i]
        max_beginning_here = max_beginning_here + arr[n - 1 - i]
        if max_beginning_here < 0:
            max_beginning_here = 0
        if arr[n - 1 - i] > max_beginning_here:
            max_beginning_here = arr[n - 1 - i]
        max_wrap = max(max_wrap, max_beginning_here)
    if max_wrap < max_kadane or k == 1:
        return max_kadane

    # If there are more than two repetitions
    return max(max_kadane, max_wrap + ((k - 2) * sum(arr)))
